function physicsLessonDemo(l){if(!l.physics)return '';let type=l.rules.some(r=>r.includes('I = U/R'))?'ohm':l.rules.some(r=>r.includes('Q = cm'))?'heat':l.rules.some(r=>r.includes('v = s/t'))?'motion':null;if(!type)return '';const labels={ohm:['Закон Ома','Напряжение U, В',12,'R = 6 Ом'],heat:['Нагревание воды','Изменение температуры, °C',10,'m = 1 кг; c = 4200 Дж/(кг·К)'],motion:['Равномерное движение','Время t, с',5,'v = 2 м/с']};const [name,label,value,fixed]=labels[type];return `<figure class="physics-demo" data-physics-demo="${type}"><div class="eyebrow">ЛАБОРАТОРИЯ · ${name}</div><p>${fixed}</p><label>${label}<input type="range" min="1" max="30" value="${value}" data-physics-slider aria-label="${label}"></label><div class="physics-demo-result" aria-live="polite">${physicsDemoResult(type,value)}</div><small>Отдельная модель для исследования зависимости; условия конкретной задачи могут отличаться.</small></figure>`}
function physicsDemoResult(type,v){if(type==='ohm')return `I = U/R = ${v}/6 ≈ ${(v/6).toFixed(2).replace('.',',')} А`;if(type==='heat')return `Q = cmΔT = 4200 × 1 × ${v} = ${4200*v} Дж`;return `s = vt = 2 × ${v} = ${2*v} м`}
document.addEventListener('input',e=>{if(!e.target.matches('[data-physics-slider]'))return;const box=e.target.closest('[data-physics-demo]');box.querySelector('.physics-demo-result').textContent=physicsDemoResult(box.dataset.physicsDemo,+e.target.value)});
document.addEventListener('click',e=>{if(!e.target.closest('#physicsReference'))return;let dialog=document.getElementById('physicsReferenceDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='physicsReferenceDialog';dialog.className='lesson-dialog';dialog.innerHTML='<button class="close" aria-label="Закрыть справочник">×</button><div class="eyebrow">ПОД РУКОЙ</div><h2>Единицы и константы</h2><p class="reference-note">Константы и приближения из условия задачи имеют приоритет. В задачах этого раздела g обычно принимается равным 10 м/с², когда это явно указано.</p><table class="units-table"><thead><tr><th>Величина</th><th>СИ</th><th>Перевод</th></tr></thead><tbody><tr><td>Длина</td><td>м</td><td>1 см = 0,01 м</td></tr><tr><td>Площадь</td><td>м²</td><td>1 см² = 10⁻⁴ м²</td></tr><tr><td>Объём</td><td>м³</td><td>1 л = 10⁻³ м³</td></tr><tr><td>Скорость</td><td>м/с</td><td>1 м/с = 3,6 км/ч</td></tr><tr><td>Энергия</td><td>Дж</td><td>1 кДж = 1000 Дж</td></tr><tr><td>Давление</td><td>Па</td><td>1 кПа = 1000 Па</td></tr><tr><td>Ток</td><td>А</td><td>1 мА = 10⁻³ А</td></tr><tr><td>Заряд</td><td>Кл</td><td>1 мкКл = 10⁻⁶ Кл</td></tr><tr><td>Температура</td><td>К</td><td>T ≈ t + 273</td></tr></tbody></table><p class="reference-note">Скорость света в вакууме: 3 × 10⁸ м/с.<br>Плотность воды в задачах: 1000 кг/м³.<br>Число 0,000001 можно ввести как 1e-6. В поле ответа единица выбирается отдельно.</p>';document.body.append(dialog);dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()})}dialog.showModal()});
